using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class WorkFollowupTests
{
    static readonly EntityId Lord=new("person:shingen");
    internal static ContractWorld New(){var d=TransportWorkTests.New().NewGame!;return NewGameWorld.Create(d.Start,d.Registered,d.Selected.Value,42,NewGameWorld.CompactPersonalAuthority,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy);}
    static TransportJob Last(WorldSession s)=>TransportWork.Jobs(s.DiagnosticSnapshot()).Last();
    static void Offer(WorldSession s)=>Assert.Equal(ResultCode.Accepted,s.RequestTransport(new("job:follow/"+s.Revision),s.Revision).Code);
    static void Step(WorldSession s,HandoverAction action){var j=Last(s);var t=j.Handover.Terms;var id=new EntityId("operation:follow/"+s.Revision);var input=new HandoverInput(id,action,action==HandoverAction.Cancel?t.Issuer:s.PlayerControl,action==HandoverAction.Deliver?t.Destination:t.Source,action==HandoverAction.Deliver?t.Recipient:action==HandoverAction.Cancel?t.Carrier:t.Issuer,action is HandoverAction.Collect or HandoverAction.Deliver or HandoverAction.Pay or HandoverAction.Return?new("transfer:transport/"+id.Value.Replace(':','/')):null,s.Seconds,j.Handover.Entries.Length);Assert.Equal(ResultCode.Accepted,s.HandoverTransport(t.Id,input,s.Revision).Code);}
    static void StartJob(WorldSession s){Offer(s);Step(s,HandoverAction.Accept);Step(s,HandoverAction.Collect);}
    static void Deliver(WorldSession s){TransportWorkTests.Travel(s,"suwa");Step(s,HandoverAction.Deliver);TransportWorkTests.Travel(s,"kofu");}
    static void Complete(WorldSession s){StartJob(s);Deliver(s);Step(s,HandoverAction.Report);Step(s,HandoverAction.Pay);}
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())s.Open(s.PlayerControl,m.Id,s.Revision);}
    static WorldSession Recognized(){var s=new WorldSession(New());s.Submit(NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:recognition"),s.Revision);NewGameWorldTests.At(s,1);Open(s);NewGameWorldTests.At(s,8);Open(s);return s;}
    [Fact]public void NewPolicyStartsWithRealSmallConsignment(){var s=new WorldSession(New());Offer(s);Assert.Equal(100,Last(s).Handover.Terms.Amount);Assert.Equal(20,Last(s).Handover.Terms.Fee);}
    [Fact]public void SuccessfulDeliveryReportAndPayUnlockLargerNextJob(){var s=new WorldSession(New());Complete(s);Offer(s);Assert.Equal(200,Last(s).Handover.Terms.Amount);Assert.Equal(30,Last(s).Handover.Terms.Fee);Assert.Equal(1020,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));}
    [Fact]public void DeliveryAloneDoesNotIssueAnotherJob(){var s=new WorldSession(New());StartJob(s);Deliver(s);Assert.Null(TransportWork.OfferAt(s.DiagnosticSnapshot(),new("job:too-early")));}
    [Fact]public void UnpaidFeeAlsoPreventsParallelDispatch(){var s=new WorldSession(New());StartJob(s);Deliver(s);Step(s,HandoverAction.Report);Assert.Null(TransportWork.OfferAt(s.DiagnosticSnapshot(),new("job:unpaid")));Assert.Equal(20,s.DiagnosticSnapshot().Debts.Single().Outstanding);}
    [Fact]public void RecognizedInspectionThenSuccessfulTransportUnlock300(){var s=Recognized();Complete(s);Offer(s);Assert.Equal(300,Last(s).Handover.Terms.Amount);Assert.Equal(40,Last(s).Handover.Terms.Fee);}
    [Fact]public void ReturnClosesCustodyAndRestartsSmallWithoutBlame(){var s=Recognized();StartJob(s);Step(s,HandoverAction.Cancel);Assert.Null(TransportWork.OfferAt(s.DiagnosticSnapshot(),new("job:still-borrowed")));Step(s,HandoverAction.Return);Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),Lord));Offer(s);Assert.Equal(100,Last(s).Handover.Terms.Amount);Assert.Equal(20,Last(s).Handover.Terms.Fee);Assert.Equal(1,WorkProgression.Recognized(s.DiagnosticSnapshot(),Lord));Assert.DoesNotContain(s.DiagnosticSnapshot().Service?.Events??[],e=>e.Kind==CareerEventKind.Dismissed);}
    [Fact]public void CancelBeforePickupKeepsSameTermsAndAllowsNewOriginal(){var s=Recognized();Offer(s);var first=Last(s).Handover.Terms;Step(s,HandoverAction.Cancel);Offer(s);Assert.NotEqual(first.Id,Last(s).Handover.Terms.Id);Assert.Equal(first.Amount,Last(s).Handover.Terms.Amount);Assert.Equal(first.Fee,Last(s).Handover.Terms.Fee);}
    [Fact]public void SmallRestartCanEarnBiggerWorkAgain(){var s=Recognized();StartJob(s);Step(s,HandoverAction.Cancel);Step(s,HandoverAction.Return);Complete(s);Offer(s);Assert.Equal(200,Last(s).Handover.Terms.Amount);}
    [Fact]public void AmountAndFeeCapAt300And40(){var s=new WorldSession(New());Complete(s);Complete(s);Complete(s);Assert.Equal(new FollowupTerms(300,40,"前の運搬も無事に済んだ。同じ規模の運搬を頼みたい。"),WorkFollowup.Terms(s.DiagnosticSnapshot(),Lord));}
    [Fact]public void EarlierOriginalDoesNotChangeWhenNextTierChanges(){var s=new WorldSession(New());Complete(s);var first=TransportWork.Jobs(s.DiagnosticSnapshot()).First();Offer(s);Assert.Equal(ContractJson.Write(first),ContractJson.Write(TransportWork.Jobs(s.DiagnosticSnapshot()).First()));Assert.Equal(100,first.Handover.Terms.Amount);}
    [Fact]public void SameSecondHistoryExcludesLaterPayment(){var s=new WorldSession(New());StartJob(s);Deliver(s);Step(s,HandoverAction.Report);long rev=s.Revision;Step(s,HandoverAction.Pay);var w=s.DiagnosticSnapshot();Assert.Equal(100,WorkFollowup.Terms(w,Lord,s.Seconds,rev+1).Amount);Assert.Equal(200,WorkFollowup.Terms(w,Lord,s.Seconds,s.Revision+1).Amount);}
    [Fact]public void OutcomesDoNotRaiseAnotherIssuersTerms(){var s=new WorldSession(New());Complete(s);Assert.Equal(100,WorkFollowup.Terms(s.DiagnosticSnapshot(),new("person:nobunaga")).Amount);}
    [Theory][InlineData(false)][InlineData(true)]public void OldPoliciesKeepOldDispatchRule(bool v2){var s=new WorldSession(v2?WorkProgressionTests.New():TransportWorkTests.New());Complete(s);Assert.Null(TransportWork.OfferAt(s.DiagnosticSnapshot(),new("job:old-repeat")));var w=s.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(w),ContractJson.Write(new WorldSession(ContractJson.Copy(w)).DiagnosticSnapshot()));}
    [Fact]public void SaveRestoreAfterReturnRecreatesSameNextOriginal(){var s=Recognized();StartJob(s);Step(s,HandoverAction.Cancel);Step(s,HandoverAction.Return);s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"followup-"+Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"manual",w.WorldId,new(0,1));var host=new WorldSessionHost(new(New()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),host.Current,host.Current.Revision));Offer(s);Offer(host.Current);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));}
    [Fact]public void ForgedBiggerTermsAreRejected(){var s=new WorldSession(New());Complete(s);Offer(s);var w=s.DiagnosticSnapshot();w.TransportWork=w.TransportWork! with{Jobs=w.TransportWork.Jobs.Select((j,n)=>n==1?j with{Handover=j.Handover with{Terms=j.Handover.Terms with{Amount=300,Fee=40}}}:j).ToArray()};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Fact]public void V3RetainsEarnedDutyEligibility(){var s=Recognized();Assert.Equal(Lord,WorkDuty.Candidate(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.Accepted,s.AcceptWorkDuty(new("duty:v3"),Lord,s.PlayerControl,s.Revision).Code);Assert.NotNull(WorkDuty.Active(s.DiagnosticSnapshot()));}
}
